package database

import (
	"cargo_management_app/go/dtos"
	"cargo_management_app/go/models"
)

// Read models returned by services. IDs and timestamps are generated by the
// database; write DTOs below intentionally exclude them.
//
// The concrete types live in the models and dtos packages. Aliases keep the
// database package API stable for services and Wails bindings.
type (
	Driver      = models.Driver
	Loader      = models.Loader
	Vehicle     = models.Vehicle
	Well        = models.Well
	Load        = models.Load
	Category    = models.Category
	Expense     = models.Expense
	Income      = models.Income
	FuelExpense = models.FuelExpense
	Stats       = models.Stats
)

// Write DTOs. IDs and timestamps are generated by the database and excluded.
type (
	DriverDTO      = dtos.DriverDTO
	LoaderDTO      = dtos.LoaderDTO
	VehicleDTO     = dtos.VehicleDTO
	WellDTO        = dtos.WellDTO
	LoadDTO        = dtos.LoadDTO
	CategoryDTO    = dtos.CategoryDTO
	ExpenseDTO     = dtos.ExpenseDTO
	IncomeDTO      = dtos.IncomeDTO
	FuelExpenseDTO = dtos.FuelExpenseDTO
	StatsDTO       = dtos.StatsDTO
)
